import workcell, time

TARE = 118.51
TARGET = 250.00
LO, HI = 249.85, 250.12

def scale():
    r = workcell.call("scale", "read")
    if not r.ok:
        raise SystemExit(r.text)
    return r.data["gross_g"]

def net():
    return scale() - TARE

def robot(*args):
    r = workcell.call("robot", *args)
    print(f"ROBOT {args}: {r.text}")
    if not r.ok:
        raise SystemExit("robot failed")
    return r

def status():
    r = workcell.call("robot", "status")
    print("STATUS", r.text)
    return r.data.get("clock_s")

print(f"start net={net():.2f}")
status()
steps = 0
while steps < 40:
    n = net()
    print(f"net={n:.2f} deficit={TARGET-n:.2f}")
    if LO <= n <= HI:
        print("IN RANGE")
        break
    if n > HI:
        robot("remove")
    else:
        d = TARGET - n
        if d > 16:
            robot("dose", "coarse")
        elif d > 1.6:
            robot("dose", "fine")
        else:
            robot("dose", "micro")
    steps += 1
else:
    print("TOO MANY STEPS")
status()
print(f"final net={net():.2f} steps={steps}")
